<script setup lang="ts">
import { useQuery } from '@tanstack/vue-query'
import ExecutionVariables from './ExecutionVariables.vue'
import TemplateLibraryFrame from './TemplateLibraryFrame.vue'
import type { ExecutionTemplate } from '~~/shared/types/project-execution'
import type { DocumentTemplate,DocumentTemplateApplication,DocumentTemplateInput,DocumentTemplateKind,DocumentTemplateList,DocumentTemplateStage,DocumentTemplateSummary } from '~~/shared/types/document-templates'
import { documentTemplateInputSchema,documentTemplateKinds,documentTemplateKindLabel,stageTitle,templateSearchMatches } from '~~/shared/utils/document-templates'
import { defaultExecutionState } from '~~/shared/utils/project-execution'
import { defaultClosingState } from '~~/shared/utils/project-closing'
const props=defineProps<{inline?:boolean;stage:DocumentTemplateStage;projectTemplates:Partial<Record<DocumentTemplateKind,ExecutionTemplate>>;currentKind:DocumentTemplateKind;canApply:boolean;hasDocument:boolean;currentTemplate:ExecutionTemplate|null}>()
const open=defineModel<boolean>('open',{default:false}),emit=defineEmits<{apply:[value:DocumentTemplateApplication]}>(),auth=useAuthStore()
const search=ref(''),debounced=ref(''),kindFilter=ref('all'),owner=ref('all'),page=ref(1),mode=ref<'list'|'view'|'edit'>('list'),error=ref(''),busy=ref(false),loadingDetail=ref(false),detail=ref<DocumentTemplate|null>(null),editingId=ref(''),editingRevision=ref(0),editingProject=ref(false)
const kinds=computed(()=>documentTemplateKinds[props.stage].map(k=>({...k}))),filterOptions=computed(()=>[{label:'Все типы документов',value:'all'},...kinds.value])
const defaults=()=>props.stage==='execution'?defaultExecutionState().templates:defaultClosingState().templates
const draft=ref<DocumentTemplateInput>({stage:props.stage,kind:kinds.value[0]!.value,name:'',description:'',template:JSON.parse(JSON.stringify(Object.values(defaults())[0]))})
watch(search,(value,_,cleanup)=>{const timer=setTimeout(()=>{debounced.value=value;page.value=1},250);cleanup(()=>clearTimeout(timer))})
watch([kindFilter,owner],()=>{page.value=1})
watch(open,value=>{if(value){mode.value='list';error.value=''}})
watch(()=>props.stage,()=>{kindFilter.value='all';search.value='';debounced.value='';page.value=1;mode.value='list'})
const query=useQuery({queryKey:computed(()=>['account',auth.user?.id,'document-templates',props.stage,debounced.value,kindFilter.value,owner.value,page.value]),queryFn:({signal})=>{const params=new URLSearchParams({stage:props.stage,q:debounced.value,...(kindFilter.value==='all'?{}:{kind:kindFilter.value}),owner:owner.value,page:String(page.value)});return sharedRequest<DocumentTemplateList>('/api/projects/document-templates?'+params,{signal})},enabled:computed(()=>(props.inline||open.value)&&!!auth.user?.id),retry:false})
const projectCards=computed(()=>kinds.value.filter(k=>props.projectTemplates[k.value]).map(k=>({id:`project-${k.value}`,kind:k.value,name:documentTemplateKindLabel(k.value),template:props.projectTemplates[k.value]!,stage:props.stage})).filter(card=>(kindFilter.value==='all'||card.kind===kindFilter.value)&&owner.value==='all'&&templateSearchMatches(`${card.name} ${card.template.title} Шаблон проекта`,debounced.value)))
const localDetail=computed(()=>detail.value?.id.startsWith('project-')??false)
const sameTemplate=(a:ExecutionTemplate|undefined|null,b:ExecutionTemplate|undefined|null)=>!!a&&!!b&&a.title===b.title&&a.body===b.body
const documentMatches=computed(()=>detail.value?.kind===props.currentKind&&sameTemplate(detail.value?.template,props.currentTemplate))
const projectMatches=computed(()=>!!detail.value&&sameTemplate(detail.value.template,props.projectTemplates[detail.value.kind]))
function showProject(card:typeof projectCards.value[number]){detail.value={id:card.id,stage:props.stage,kind:card.kind,name:card.name,description:'Текущий шаблон этого проекта',template:JSON.parse(JSON.stringify(card.template)),title:card.template.title,excerpt:card.template.body.slice(0,200),ownerId:'',author:'Шаблон проекта',revision:0,updatedAt:'',canEdit:props.canApply};mode.value='view';error.value=''}
async function show(row:DocumentTemplateSummary){if(loadingDetail.value)return;loadingDetail.value=true;error.value='';const user=auth.user?.id;try{const result=await sharedRequest<DocumentTemplate>(`/api/projects/document-templates/${row.id}`);if(auth.user?.id!==user||(!props.inline&&!open.value))return;detail.value=result;mode.value='view'}catch(e:any){error.value=e?.data?.message||e.message}finally{loadingDetail.value=false}}
function create(source?:DocumentTemplate,forProject=false){editingId.value=source&&!forProject&&source.canEdit&&!source.id.startsWith('project-')?source.id:'';editingRevision.value=editingId.value?source!.revision:0;editingProject.value=forProject;const kind=source?.kind??(kindFilter.value==='all'?kinds.value[0]!.value:kindFilter.value as DocumentTemplateKind);draft.value={stage:props.stage,kind,name:source?.name??'',description:source?.description??'',template:JSON.parse(JSON.stringify(source?.template??(defaults() as Partial<Record<DocumentTemplateKind,ExecutionTemplate>>)[kind]!))};mode.value='edit';error.value=''}
function copy(){if(!detail.value)return;const source={...detail.value,canEdit:false,name:`Копия: ${detail.value.name}`.slice(0,120)};create(source)}
function changeKind(value:DocumentTemplateKind){draft.value.kind=value;draft.value.template=JSON.parse(JSON.stringify((defaults() as Partial<Record<DocumentTemplateKind,ExecutionTemplate>>)[value]!))}
function apply(target:'project'|'document'){if(!detail.value||!props.canApply)return;emit('apply',{kind:detail.value.kind,template:JSON.parse(JSON.stringify(detail.value.template)),target});open.value=false}
async function save(){
 if(busy.value)return;const parsed=documentTemplateInputSchema.safeParse(draft.value);if(!parsed.success){error.value=parsed.error.issues[0]?.message||'Проверьте поля';return}
 if(editingProject.value){if(!props.canApply)return;emit('apply',{kind:parsed.data.kind,template:parsed.data.template,target:'project'});open.value=false;return}
 busy.value=true;error.value='';const user=auth.user?.id
 try{const result=await sharedRequest<{id:string}>(`/api/projects/document-templates${editingId.value?'/'+editingId.value:''}`,{method:editingId.value?'PUT':'POST',body:{...parsed.data,...(editingId.value?{revision:editingRevision.value}:{})}});if(auth.user?.id!==user)return;detail.value=await sharedRequest<DocumentTemplate>(`/api/projects/document-templates/${result.id}`);search.value='';debounced.value='';kindFilter.value='all';owner.value='all';page.value=1;await query.refetch();mode.value='view'}catch(e:any){error.value=e?.data?.message||e.message}finally{busy.value=false}
}
</script>
<template>
 <TemplateLibraryFrame v-model:open="open" :inline="inline" :title="`Шаблоны документов · ${stageTitle(stage)}`" description="Общее хранилище этого этапа для пользователей раздела «Проекты». Шаблоны можно применять в разных проектах." :busy="busy">
  <UAlert v-if="error" color="error" :description="error" class="mb-5"/>
  <template v-if="mode==='list'">
   <div class="library-toolbar"><UInput v-model="search" icon="i-lucide-search" placeholder="Название, описание или автор" aria-label="Поиск шаблонов" :maxlength="200" class="library-search"/><USelect v-model="kindFilter" :items="filterOptions" aria-label="Тип документа в хранилище"/><USelect v-model="owner" :items="[{label:'Все авторы',value:'all'},{label:'Мои шаблоны',value:'mine'}]" aria-label="Автор шаблона"/><UButton label="Добавить шаблон" icon="i-lucide-plus" @click="create()"/></div>
   <section v-if="projectCards.length" class="library-section"><h3>Шаблоны текущего проекта</h3><div class="library-grid"><article v-for="card in projectCards" :key="card.id" class="library-card"><span class="library-type"><UIcon name="i-lucide-file-text"/>{{documentTemplateKindLabel(card.kind)}}</span><h4>{{card.name}}</h4><p>{{card.template.title}}</p><small>Используется в этом проекте</small><div class="library-card-actions"><UButton label="Открыть" color="neutral" variant="outline" @click="showProject(card)"/></div></article></div></section>
   <section class="library-section"><div class="library-heading"><h3>Общее хранилище</h3><span v-if="query.data.value">Найдено: {{query.data.value.total}}</span></div><p v-if="query.isPending.value" class="library-muted">Загружаем шаблоны…</p><UAlert v-else-if="query.error.value" color="error" title="Не удалось загрузить общее хранилище" :actions="[{label:'Повторить',onClick:()=>query.refetch()}]"/><div v-else-if="query.data.value?.items.length" class="library-grid"><article v-for="row in query.data.value.items" :key="row.id" class="library-card"><span class="library-type"><UIcon name="i-lucide-file-text"/>{{documentTemplateKindLabel(row.kind)}}</span><h4>{{row.name}}</h4><p>{{row.description||row.title}}</p><small>Автор: {{row.author}}<span v-if="row.canEdit"> · Ваш шаблон</span></small><div class="library-card-actions"><UButton label="Открыть" color="neutral" variant="outline" :disabled="loadingDetail" @click="show(row)"/></div></article></div><div v-else class="library-empty"><UIcon name="i-lucide-folder-search"/><h4>{{debounced||kindFilter!=='all'||owner==='mine'?'Шаблоны не найдены':'Добавьте первый общий шаблон этого этапа'}}</h4><p>Создайте свой вариант или откройте шаблон проекта и сохраните его в общее хранилище.</p></div><div v-if="query.data.value&&query.data.value.total>query.data.value.pageSize" class="library-pagination"><UButton label="Назад" color="neutral" variant="outline" :disabled="page<=1" @click="page--"/><span>Страница {{page}} из {{Math.ceil(query.data.value.total/query.data.value.pageSize)}}</span><UButton label="Далее" color="neutral" variant="outline" :disabled="page*query.data.value.pageSize>=query.data.value.total" @click="page++"/></div></section>
  </template>
  <template v-else-if="mode==='view'&&detail">
   <UButton label="К карточкам шаблонов" icon="i-lucide-arrow-left" color="neutral" variant="ghost" class="mb-5" @click="mode='list';error=''"/><div class="library-detail-heading"><span class="library-type">{{documentTemplateKindLabel(detail.kind)}}</span><h3>{{detail.name}}</h3><p>{{detail.description}}</p><small>Автор: {{detail.author}}</small><span v-if="documentMatches" class="library-applied">Используется в текущем документе</span><span v-else-if="projectMatches" class="library-applied">Используется как шаблон проекта</span></div><div class="library-preview"><h4>{{detail.template.title}}</h4><p>{{detail.template.body}}</p></div><div class="library-actions"><UButton v-if="canApply&&hasDocument&&currentKind===detail.kind" :label="documentMatches?'Уже используется в документе':'Использовать в текущем документе'" :disabled="documentMatches" @click="apply('document')"/><UButton v-if="canApply" :label="projectMatches?'Уже используется в проекте':'Сделать шаблоном проекта'" :disabled="projectMatches" color="neutral" variant="outline" @click="apply('project')"/><UButton v-if="localDetail&&canApply" label="Редактировать для проекта" icon="i-lucide-pencil" color="neutral" variant="outline" @click="create(detail,true)"/><UButton v-if="!localDetail&&detail.canEdit" label="Редактировать общий шаблон" icon="i-lucide-pencil" color="neutral" variant="outline" @click="create(detail)"/><UButton v-if="localDetail" label="Сохранить в общее хранилище" icon="i-lucide-folder-plus" color="neutral" variant="outline" @click="create({...detail,canEdit:false})"/><UButton v-else label="Создать свою копию" icon="i-lucide-copy" color="neutral" variant="outline" @click="copy"/></div><p class="library-muted mt-4">При применении текст копируется в проект. После применения сохраните изменения на странице этапа. Индивидуальный текст документов меняется через «Использовать в текущем документе».</p><p v-if="!canApply&&!inline" class="library-muted mt-3">Применять шаблоны к проекту могут его создатель и редакторы.</p>
  </template>
  <template v-else-if="mode==='edit'">
   <form class="library-editor" @submit.prevent="save"><div class="library-editor-heading"><h3>{{editingProject?'Шаблон текущего проекта':editingId?'Редактирование общего шаблона':'Новый общий шаблон'}}</h3><span v-if="!editingProject" class="library-muted">Доступен всем пользователям раздела «Проекты»</span></div><UFormField v-if="!editingProject" label="Название шаблона" required><UInput v-model="draft.name" class="w-full" :maxlength="120" :disabled="busy" required placeholder="Например, Договор на поставку товаров"/></UFormField><UFormField v-if="!editingProject" label="Описание"><UInput v-model="draft.description" class="w-full" :maxlength="500" :disabled="busy"/></UFormField><UFormField label="Тип документа"><USelect :model-value="draft.kind" :items="kinds" :disabled="busy||!!editingId||editingProject" aria-label="Тип нового шаблона" @update:model-value="changeKind($event as DocumentTemplateKind)"/></UFormField><UFormField label="Заголовок документа" required><UInput v-model="draft.template.title" class="w-full" :maxlength="200" :disabled="busy" required/></UFormField><UFormField label="Текст шаблона" required><UTextarea v-model="draft.template.body" class="w-full" :rows="15" :maxlength="20000" :disabled="busy" required/></UFormField><ExecutionVariables :disabled="busy" @insert="draft.template.body+='\n{{'+$event+'}}'"/><div class="library-actions"><UButton type="submit" :label="editingProject?'Применить к проекту':'Сохранить в общее хранилище'" :loading="busy"/><UButton label="Отмена" color="neutral" variant="outline" :disabled="busy" @click="mode='list';error=''"/></div></form>
  </template>
 </TemplateLibraryFrame>
</template>
<style scoped>
.library-toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:28px}.library-search{flex:1;min-width:220px}.library-section{margin:24px 0}.library-section h3{font-size:18px;font-weight:650;color:#334155;margin-bottom:18px}.library-heading{display:flex;justify-content:space-between;gap:16px;align-items:baseline}.library-heading>span{font-size:12px;color:#8292a8}.library-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.library-card{display:flex;flex-direction:column;gap:12px;border:1px solid #dce3ec;border-radius:18px;padding:22px;background:#fff;min-width:0}.library-type{display:flex;align-items:center;gap:8px;color:#8292a8;font-size:12px}.library-type>.iconify{font-size:20px;color:var(--ui-primary)}.library-card h4{font-size:17px;font-weight:650;color:#334155;overflow-wrap:anywhere}.library-card p{font-size:13px;color:#8292a8;line-height:1.6;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.library-card small{font-size:11px;color:#94a3b8}.library-card-actions{padding-top:12px;margin-top:auto;display:flex;flex-wrap:wrap;gap:8px}.library-muted{font-size:13px;color:#8292a8;line-height:1.7}.library-empty{text-align:center;padding:48px 24px;border:1px dashed #dce3ec;border-radius:18px;color:#8292a8}.library-empty>.iconify{font-size:34px}.library-empty h4{font-size:18px;margin:16px 0 10px;color:#475569}.library-empty p{font-size:13px;line-height:1.7}.library-pagination{display:flex;justify-content:center;align-items:center;gap:16px;margin-top:24px;font-size:13px;color:#8292a8}.library-detail-heading{display:grid;gap:10px;margin-bottom:24px}.library-detail-heading h3,.library-editor-heading h3{font-size:21px;font-weight:650;color:#334155}.library-detail-heading p,.library-detail-heading small{font-size:13px;color:#8292a8}.library-preview{padding:28px;border:1px solid #e2e8f0;border-radius:18px;background:#fff;max-height:50vh;overflow:auto;margin-bottom:24px;overflow-wrap:anywhere}.library-preview h4{font-size:18px;font-weight:650;color:#334155;margin-bottom:20px}.library-preview p{white-space:pre-wrap;color:#64748b;font-size:13px;line-height:1.8}.library-actions{display:flex;flex-wrap:wrap;gap:10px}.library-editor{display:grid;gap:20px}.library-editor-heading{display:flex;flex-direction:column;gap:8px}@media(max-width:900px){.library-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:580px){.library-grid{grid-template-columns:minmax(0,1fr)}.library-toolbar>*{flex:1;min-width:100%}.library-card{padding:18px}.library-preview{padding:20px}}
.library-applied{font-size:12px;color:#15803d;background:#f0fdf4;border:1px solid #bbf7d0;padding:7px 10px;border-radius:8px;width:fit-content}
</style>
